.content{max-width:none;min-width:0}
/* Payroll campus submenu: per-campus management replaces the campus table column. */
.payroll-campus-layout{display:grid;grid-template-columns:minmax(190px,214px) minmax(0,1fr);gap:16px;align-items:start}
.payroll-campus-layout.is-single-campus{grid-template-columns:minmax(0,1fr)}
.payroll-campus-layout>*{min-width:0}
.campus-menu{position:sticky;top:16px;background:var(--cpsu-panel);border:1px solid var(--cpsu-border);border-radius:12px;padding:6px}
.campus-menu-head{padding:8px 10px 7px;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.12em;color:var(--cpsu-muted)}
.campus-menu-list{max-height:calc(100vh - 190px);overflow:auto}
.campus-tab{display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:7px;color:#3b4453;font-size:13px;text-decoration:none}
.campus-tab.all{margin-bottom:5px;padding-bottom:11px;border-bottom:1px solid var(--cpsu-border);border-radius:7px 7px 0 0}
.campus-tab:hover{background:var(--cpsu-gray-bg)}
.campus-tab-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.campus-tab-flag{flex:0 0 auto;width:6px;height:6px;border-radius:999px;background:var(--cpsu-gold-dark)}
.campus-tab-count{flex:0 0 auto;color:#98a2b3;font-size:12px;font-variant-numeric:tabular-nums}
.campus-tab.active{background:var(--cpsu-green-soft);color:var(--cpsu-green-dark);font-weight:800}
.campus-tab.active .campus-tab-count{color:var(--cpsu-green)}
.campus-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;border:1px solid var(--cpsu-border);border-radius:10px;background:var(--cpsu-border);margin:0 0 14px;overflow:hidden}
.campus-stat{display:flex;flex-direction:column;gap:2px;padding:9px 16px;background:#fff}
.campus-stat.net{background:var(--cpsu-gray-bg)}
.campus-stat.net strong{font-size:15px;color:var(--cpsu-green-dark)}
@media(min-width:1500px){.campus-summary{grid-template-columns:repeat(6,minmax(0,1fr))}}
@media(max-width:620px){.campus-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}
.campus-stat small{font-size:11px;color:var(--cpsu-muted);white-space:nowrap}
.campus-stat strong{font-size:16px;font-weight:800;color:#1f2937;font-variant-numeric:tabular-nums}
.campus-stat.flagged strong{color:var(--cpsu-danger)}
@media(max-width:1080px){
    .payroll-campus-layout{grid-template-columns:1fr}
    .campus-menu{position:static;display:flex;align-items:center;gap:4px;padding:5px 8px;overflow:hidden}
    .campus-menu-head{padding:0 8px 0 2px;flex:0 0 auto}
    .campus-menu-list{display:flex;gap:2px;max-height:none;overflow-x:auto}
    .campus-tab{flex:0 0 auto}
    .campus-tab.all{margin-bottom:0;padding-bottom:7px;border-bottom:0;border-right:1px solid var(--cpsu-border);border-radius:7px;margin-right:4px}
}
@media(max-width:640px){.campus-menu{flex-direction:column;align-items:stretch}.campus-menu-head{padding:4px 8px}}
/* Workbook-style fund tabs on the payroll draft, mirroring the Excel sheet tabs. */
.fund-tabs{display:flex;align-items:stretch;gap:8px;min-width:0;flex:1 1 auto}
.fund-tabs-head{display:flex;align-items:center;flex:0 0 auto;padding:0 8px 0 4px;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.12em;color:#667085;border-right:1px solid #dfe5d9}
.fund-tabs-list{display:flex;gap:4px;overflow-x:auto;scrollbar-width:thin}
.fund-tab{display:inline-flex;align-items:center;gap:6px;flex:0 0 auto;min-height:32px;padding:6px 11px;border:1px solid #d8dfd1;border-radius:7px 7px 0 0;border-bottom-width:2px;border-bottom-color:#d8dfd1;background:#fff;color:#475467;font-size:12px;font-weight:850;text-decoration:none;white-space:nowrap}
.fund-tab:hover{border-color:#b8c5b2;border-bottom-color:#0B6E2E;background:#fbfcf8;color:#1f2937}
.fund-tab.active{background:#fff;color:#073f20;border-color:#b7d3bd;border-bottom-color:#0B6E2E;box-shadow:0 -1px 0 rgba(11,110,46,.1) inset}
.fund-tab strong{font-variant-numeric:tabular-nums;font-size:11px;color:#0B6E2E}
.fund-tab.empty{background:transparent;border-style:dashed;border-bottom-width:1px;color:#98a2b3;cursor:not-allowed}
.fund-dot{width:6px;height:6px;border-radius:999px;background:#98a2b3;flex:0 0 auto}
.fund-dot.green{background:#127a35}.fund-dot.gold{background:#c99e00}.fund-dot.red{background:#b42318}
.payroll-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 12px;padding:6px 8px;border:1px solid #d9dfd3;border-radius:8px;background:#f4f7f1}
.payroll-toolbar .payroll-jump{margin:0;flex:0 0 auto}
@media(max-width:900px){.payroll-toolbar{flex-direction:column;align-items:stretch}.payroll-toolbar .payroll-jump{justify-content:flex-end}}
@media(max-width:640px){.fund-tabs{flex-direction:column;gap:6px}.fund-tabs-head{border-right:0;padding:2px 4px}}
/* Payroll totals as one slim reference line instead of a row of cards. */
.payroll-metrics{display:flex;flex-wrap:wrap;align-items:center;gap:4px 18px;margin:0 0 12px;padding:8px 12px;border:1px solid #dfe5d9;border-radius:8px;background:#fff}
.metric{display:inline-flex;align-items:baseline;gap:6px;white-space:nowrap}
.metric small{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.08em;color:#667085}
.metric strong{font-size:13px;font-weight:900;color:#111827;font-variant-numeric:tabular-nums}
.metric.highlight strong{color:#0B6E2E}
.metric.warn strong{color:#7a5c00}
.metric.danger strong{color:#b42318}
@media(max-width:640px){.payroll-metrics{gap:4px 14px}}
/* Command row: batch identity, readiness, and workflow buttons on one line. */
.payroll-command{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px 14px;margin:0 0 12px;padding:9px 12px;border:1px solid #d9dfd3;border-radius:8px;background:#fff}
.command-main{display:flex;align-items:center;flex-wrap:wrap;gap:6px 10px;min-width:0}
.command-fund{font-size:15px;font-weight:950;color:#14251b}
.command-meta{font-size:12px;color:#667085}
.command-note{display:inline-flex;align-items:baseline;gap:6px;padding:3px 9px;border:1px solid #dfe5d9;border-radius:999px;background:#f7faf5;font-size:12px;color:#667085}
.command-note strong{font-weight:900;color:#1f2937}
.command-note.blocked{background:#fff8ce;border-color:#f4df6a}
.command-note.blocked strong{color:#7a5c00}
.command-note.ready{background:#eafaf0;border-color:#bdebc9}
.command-note.ready strong{color:#126d31}
.command-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}
.command-actions form{margin:0}
@media(max-width:900px){.payroll-command{flex-direction:column;align-items:stretch}.command-actions{justify-content:stretch}.command-actions>*{flex:1}.command-actions .primary-btn,.command-actions .ghost-btn,.command-actions .danger-btn,.command-actions .gold-btn{width:100%}}
</style>
